import { expect, Journey, test } from './journey.js';

test("media and device emulation", async ({ browser, baseURL, page, context }) => {
  const j = await Journey.start({ browser, baseURL, page, context }, [], { logs: false });
  try {
    await j.emulate({"mobile":true,"touch":true});
    await j.emulate({"colorScheme":"dark","reducedMotion":"reduce"});
    await j.goto("/p/scheme");
    await expect(j.page.locator("html")).toHaveAttribute("data-scheme", "dark");
    await expect(j.page.locator("html")).toHaveAttribute("data-touch", "yes");
  } finally {
    await j.close();
  }
});
